import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { Feature, type IFeature } from "../../../models/Feature";
import type { IFeatureDependency } from "../../../models/FeatureDependency";
import type { DependencyTerms } from "../../../utils/dependencies/dependencySentences";
import { createDependsOnColumn, createStateColumn } from "./columns";

const THE_DEFAULT_TERMS: DependencyTerms = {
	featureTerm: "Feature",
	portfolioTerm: "Portfolio",
	teamTerm: "Team",
};

import FeatureListDataGrid from "./FeatureListDataGrid";

vi.mock("../../../hooks/useFeatureOrdering", () => ({
	useFeatureOrdering: () => ({
		policy: "SourceOrder",
		positionColumnLabel: "#",
		resolveMoveGate: () => ({
			enabled: false,
			reason: "policy-off",
			blockingPortfolios: [],
		}),
		refresh: vi.fn(),
	}),
}));

const SEEDED_TERMS: Record<string, string> = {
	feature: "Feature",
	features: "Features",
	blocked: "Blocked",
};

const terminology = vi.hoisted(() => ({
	terms: {} as Record<string, string>,
}));

vi.mock("../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) => terminology.terms[key] ?? "Unknown",
	}),
}));

beforeEach(() => {
	terminology.terms = { ...SEEDED_TERMS };
	localStorage.clear();
	Object.defineProperty(globalThis, "matchMedia", {
		writable: true,
		value: vi.fn().mockImplementation((query) => ({
			matches: false,
			media: query,
			onchange: null,
			addListener: vi.fn(),
			removeListener: vi.fn(),
			addEventListener: vi.fn(),
			removeEventListener: vi.fn(),
			dispatchEvent: vi.fn(),
		})),
	});
});

const aDependency = (
	overrides: Partial<IFeatureDependency> = {},
): IFeatureDependency => ({
	referenceId: "FTR-9",
	name: "Warehouse sync",
	url: "https://tracker.example/FTR-9",
	source: "TrackerLink",
	notHonouredReason: null,
	blockerPositionedBelow: false,
	isWithheld: false,
	...overrides,
});

const feature = (dependsOn: IFeatureDependency[] = []): IFeature =>
	({
		id: 1,
		name: "Rebuild the search index",
		referenceId: "FTR-1",
		forecasts: [],
		teamsWithoutForecast: [],
		dependsOn,
	}) as unknown as IFeature;

const renderCell = (row: IFeature) => {
	const column = createDependsOnColumn(THE_DEFAULT_TERMS);
	return render(
		column.renderCell?.({ row, value: (row.dependsOn ?? []).length }),
	);
};

describe("createDependsOnColumn", () => {
	it("names each Feature this one waits on, id first", () => {
		renderCell(feature([aDependency()]));

		expect(screen.getByText("FTR-9: Warehouse sync")).toBeInTheDocument();
	});

	// A reader scanning this column is looking for which Features are involved. Two of them running
	// into one line is a line they have to read twice.
	it("gives every Feature waited on a line of its own", () => {
		renderCell(
			feature([
				aDependency(),
				aDependency({ referenceId: "FTR-8", name: "Payment gateway upgrade" }),
			]),
		);

		expect(screen.getByText("FTR-9: Warehouse sync")).toBeInTheDocument();
		expect(
			screen.getByText("FTR-8: Payment gateway upgrade"),
		).toBeInTheDocument();
		expect(screen.getAllByRole("link")).toHaveLength(2);
	});

	// Deciding what to do about a wait happens in the work tracking system, and the reader is in the
	// middle of reading a list here - sending them away from it would cost them their place.
	it("opens the record in the work tracking system in a new tab", () => {
		renderCell(feature([aDependency()]));

		const link = screen.getByRole("link", { name: "FTR-9: Warehouse sync" });
		expect(link).toHaveAttribute("href", "https://tracker.example/FTR-9");
		expect(link).toHaveAttribute("target", "_blank");
		expect(link).toHaveAttribute("rel", expect.stringContaining("noopener"));
	});

	// An anchor with nowhere to go still looks and behaves like one. Asserted on the element itself
	// rather than on the link role, which an anchor without an href does not have anyway.
	it("still names a Feature the work tracking system gave no link to", () => {
		const { container } = renderCell(feature([aDependency({ url: null })]));

		expect(screen.getByText("FTR-9: Warehouse sync")).toBeInTheDocument();
		expect(container.querySelectorAll("a")).toHaveLength(0);
	});

	// The row is here because something is being waited on. Naming it would be the disclosure the
	// payload already refused.
	it("says a Feature the reader may not see is there without naming it", () => {
		renderCell(
			feature([
				aDependency({
					referenceId: "",
					name: "",
					url: null,
					isWithheld: true,
					notHonouredReason: "OutsideThisPortfolio",
				}),
			]),
		);

		expect(screen.getByText("No access")).toBeInTheDocument();
		expect(screen.queryByRole("link")).not.toBeInTheDocument();
	});

	it("leaves the cell empty when the Feature waits on nothing", () => {
		const { container } = renderCell(feature());

		expect(container.textContent).toBe("");
	});

	// Setting dependencies aside is not hiding them. The whole point of the switch over editing links in
	// the tracker is that the reader can still see what they set aside.
	it("still names every Feature a Portfolio that set its dependencies aside waits on", () => {
		renderCell(
			feature([aDependency({ notHonouredReason: "IgnoredByPortfolio" })]),
		);

		expect(screen.getByText("FTR-9: Warehouse sync")).toBeInTheDocument();
	});

	// Nothing warns about a set-aside dependency, so this entry is the only place the reader is told.
	it("says on the entry itself that a dependency has been set aside", () => {
		renderCell(
			feature([aDependency({ notHonouredReason: "IgnoredByPortfolio" })]),
		);

		expect(screen.getByTestId("dependency-set-aside")).toBeInTheDocument();
	});

	// Most Features wait on nothing at all, and a row that has never been refreshed carries no list
	// rather than an empty one.
	it("prints nothing for a row that has no dependency list at all", () => {
		const { container } = renderCell(feature(undefined));

		expect(container.textContent).toBe("");
	});

	// The cell is found by this in the end-to-end tests, so the name of it is behaviour rather than
	// decoration.
	it("labels each entry with the Feature the row is about", () => {
		renderCell(feature([aDependency()]));

		expect(screen.getAllByTestId("depends-on-FTR-1")).toHaveLength(1);
	});

	it("marks nothing as set aside when the dependencies are being acted on", () => {
		renderCell(feature([aDependency(), aDependency({ referenceId: "FTR-8" })]));

		expect(
			screen.queryByTestId("dependency-set-aside"),
		).not.toBeInTheDocument();
	});

	it("is named for the thing itself, in words no instance renames", () => {
		expect(createDependsOnColumn(THE_DEFAULT_TERMS).headerName).toBe(
			"Dependencies",
		);
	});

	it("never borrows the word an instance may already have renamed for board-blocked work", () => {
		expect(createDependsOnColumn(THE_DEFAULT_TERMS).headerName).not.toMatch(
			/block/i,
		);
	});

	it("stays sortable, so a list can be read waiting-most first", () => {
		expect(createDependsOnColumn(THE_DEFAULT_TERMS).sortable).toBe(true);
	});

	// The list has no order a reader would sort by, and the question the column answers first is which
	// rows are entangled at all.
	it("sorts on how many are waited on rather than on what the cell prints", () => {
		const column = createDependsOnColumn(THE_DEFAULT_TERMS);

		expect(
			column.valueGetter?.(
				undefined,
				feature([aDependency(), aDependency({ referenceId: "FTR-8" })]),
			),
		).toBe(2);
	});
});

const featureRow = (dependsOn: IFeatureDependency[]): Feature => {
	const row = new Feature();
	row.id = 1;
	row.name = "Rebuild the search index";
	row.referenceId = "FTR-1";
	row.stateCategory = "ToDo";
	row.state = "Active";
	row.lastUpdated = new Date();
	row.isUsingDefaultFeatureSize = false;
	row.projects = [];
	row.remainingWork = { 1: 5 };
	row.totalWork = { 1: 10 };
	row.forecasts = [];
	row.url = "";
	row.dependsOn = dependsOn;
	return row;
};

const renderGrid = (dependsOn: IFeatureDependency[] = [aDependency()]) =>
	render(
		<MemoryRouter>
			<FeatureListDataGrid
				features={[featureRow(dependsOn)]}
				columns={[createStateColumn()]}
				storageKey="depends-on-shared-grid"
				hideCompletedStorageKey="depends-on-shared-grid-hide-completed"
			/>
		</MemoryRouter>,
	);

describe("the same column is read on both Feature lists, because there is only one of them", () => {
	// Neither Feature list can supply this column: the shared grid composes it, so there is one
	// definition to disagree with itself. A caller passing only its own columns still gets it.
	it("comes from the shared grid, so no surface can hand in its own version", () => {
		renderGrid();

		expect(
			screen.getByRole("columnheader", { name: "Dependencies" }),
		).toBeInTheDocument();
		expect(screen.getByText("FTR-9: Warehouse sync")).toBeInTheDocument();
	});

	// An instance can rename what it calls held-up work, and one screen carrying that word in two
	// meanings is unreadable. Whatever the instance chose, this column must not have borrowed it.
	it("never borrows the word this instance keeps for held-up work", () => {
		terminology.terms.blocked = "Impeded";

		const { container } = renderGrid();
		const columnCells = container.querySelectorAll('[data-field="dependsOn"]');

		expect(columnCells.length).toBeGreaterThan(0);
		for (const cell of columnCells) {
			expect(cell.textContent).not.toMatch(/impeded/i);
			expect(cell.textContent).not.toMatch(/block/i);
		}
	});
});

import { render, screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import type { IFeatureDependency } from "../../../models/FeatureDependency";
import WarningsIndicator from "./WarningsIndicator";

const { terms } = vi.hoisted(() => ({
	terms: {
		workItems: "Work Items",
		feature: "Feature",
		portfolio: "Portfolio",
		blocked: "Blocked",
	} as Record<string, string>,
}));

vi.mock("../../../services/TerminologyContext", () => ({
	useTerminology: () => ({
		getTerm: (key: string) => terms[key] ?? key,
	}),
}));

const aWarning = (
	overrides: Partial<IFeatureDependency>,
): IFeatureDependency => ({
	referenceId: "F-9",
	name: "Warehouse sync",
	url: "https://tracker.example/F-9",
	source: "TrackerLink",
	isWithheld: false,
	notHonouredReason: null,
	blockerPositionedBelow: false,
	...overrides,
});

const renderIndicator = (
	props: Partial<React.ComponentProps<typeof WarningsIndicator>> = {},
) =>
	render(
		<WarningsIndicator
			isDoneWithRemainingWork={false}
			isUsingDefaultFeatureSize={false}
			{...props}
		/>,
	);

const whatItSays = (): string =>
	screen.getByTestId("warnings").getAttribute("aria-label") ?? "";

const DONE_WITH_WORK_LEFT =
	"This feature is marked as done but still has remaining work items. Please verify if all work has been completed.";

const NO_CHILDREN_FOUND =
	"No child Work Items were found for this Feature. The remaining Work Items displayed are based on the default Feature size specified in the advanced project settings.";

describe("WarningsIndicator", () => {
	it("shows the all-clear when there is nothing to say", () => {
		renderIndicator();

		expect(screen.getByTestId("no-warnings")).toBeInTheDocument();
		expect(screen.queryByTestId("warnings")).not.toBeInTheDocument();
	});

	// A row either needs attention or it does not. Two icons say nothing the first did not, and turn
	// "does this row need me" into a counting exercise.
	it("shows one warning however many things are wrong", () => {
		renderIndicator({
			isDoneWithRemainingWork: true,
			isUsingDefaultFeatureSize: true,
			dependencies: [
				aWarning({ notHonouredReason: "InALoop" }),
				aWarning({
					referenceId: "F-8",
					notHonouredReason: "OutsideThisPortfolio",
				}),
				aWarning({ referenceId: "F-7", blockerPositionedBelow: true }),
			],
		});

		expect(screen.getAllByRole("button")).toHaveLength(1);
		expect(screen.queryByTestId("no-warnings")).not.toBeInTheDocument();
	});

	// Everything wrong with the row is readable in the one place, or the icon that replaced four icons
	// has thrown three reasons away.
	it("says every one of them, not just the first", () => {
		renderIndicator({
			isDoneWithRemainingWork: true,
			isUsingDefaultFeatureSize: true,
			dependencies: [
				aWarning({ notHonouredReason: "InALoop" }),
				aWarning({
					referenceId: "F-8",
					name: "Payment gateway",
					notHonouredReason: "BlockerCannotBeForecast",
				}),
			],
		});

		const said = whatItSays();

		expect(said).toContain(DONE_WITH_WORK_LEFT);
		expect(said).toContain(NO_CHILDREN_FOUND);
		expect(said).toContain("Warehouse sync are waiting on each other");
		expect(said).toContain("Payment gateway has no measured delivery");
	});

	it("says a Feature is marked done with work still left on it", () => {
		renderIndicator({ isDoneWithRemainingWork: true });

		expect(whatItSays()).toBe(DONE_WITH_WORK_LEFT);
	});

	it("says a Feature has no children and is being sized by the default", () => {
		renderIndicator({ isUsingDefaultFeatureSize: true });

		expect(whatItSays()).toBe(NO_CHILDREN_FOUND);
	});

	describe("dependency warnings", () => {
		// Having a dependency is not a warning. A row waiting on something perfectly ordinary still
		// reads as clear, or the column stops being a way to find the rows that need attention.
		it("still shows the all-clear when a dependency has nothing wrong with it", () => {
			renderIndicator({ dependencies: [aWarning({})] });

			expect(screen.getByTestId("no-warnings")).toBeInTheDocument();
		});

		it("names the Feature waited on and says the forecast leaves it out", () => {
			renderIndicator({
				dependencies: [aWarning({ notHonouredReason: "OutsideThisPortfolio" })],
			});

			expect(whatItSays()).toContain("Warehouse sync");
			expect(whatItSays()).toContain("is not included in the forecast");
		});

		it("says two Features are waiting on each other", () => {
			renderIndicator({
				dependencies: [aWarning({ notHonouredReason: "InALoop" })],
			});

			expect(whatItSays()).toContain("waiting on each other");
		});

		it("says the wait cannot be given a date", () => {
			renderIndicator({
				dependencies: [
					aWarning({ notHonouredReason: "BlockerCannotBeForecast" }),
				],
			});

			expect(whatItSays()).toContain("no measured delivery to forecast from");
		});

		it("says a Feature waited on sits lower down in the order", () => {
			renderIndicator({
				dependencies: [aWarning({ blockerPositionedBelow: true })],
			});

			expect(whatItSays()).toContain("sits below it in the order");
		});

		// A reader who may not see the Feature is still told there is something wrong, and is told
		// nothing about what it is. Naming it here would be the disclosure the payload refused.
		it("says something is waited on without naming it when it is withheld", () => {
			renderIndicator({
				dependencies: [
					aWarning({
						isWithheld: true,
						referenceId: "",
						name: "",
						notHonouredReason: "OutsideThisPortfolio",
					}),
				],
			});

			expect(whatItSays()).toContain("a Feature you do not have access to");
		});

		// A choice somebody made is not a broken link. Warning about every Feature in a Portfolio that
		// set its dependencies aside would teach the reader to stop looking at the column.
		it("says nothing at all about a dependency the Portfolio set aside", () => {
			renderIndicator({
				dependencies: [
					aWarning({ notHonouredReason: "IgnoredByPortfolio" }),
					aWarning({
						referenceId: "F-8",
						notHonouredReason: "IgnoredByPortfolio",
						blockerPositionedBelow: true,
					}),
				],
			});

			expect(screen.getByTestId("no-warnings")).toBeInTheDocument();
		});

		// The switch quietens the dependency warnings and nothing else. A Feature marked done with work
		// left on it is still wrong, and has nothing to do with what it waits on.
		it("leaves the warnings that existed before dependencies did exactly as they were", () => {
			renderIndicator({
				isDoneWithRemainingWork: true,
				dependencies: [aWarning({ notHonouredReason: "IgnoredByPortfolio" })],
			});

			expect(whatItSays()).toBe(DONE_WITH_WORK_LEFT);
		});

		// The word the instance reserves for an item held up right now already means something else on
		// this very grid, and it is renameable - two meanings following one rename land side by side.
		it("never uses the word that already names something else", () => {
			renderIndicator({
				dependencies: [
					aWarning({ notHonouredReason: "OutsideThisPortfolio" }),
					aWarning({ referenceId: "F-8", blockerPositionedBelow: true }),
					aWarning({ referenceId: "F-7", notHonouredReason: "InALoop" }),
					aWarning({
						referenceId: "F-6",
						notHonouredReason: "BlockerCannotBeForecast",
					}),
				],
			});

			expect(whatItSays().toLowerCase()).not.toContain("block");
		});

		// The other half of the same claim: not only is that word absent, renaming it moves nothing here.
		// A warning that quietly followed the rename would put two meanings of one word on one row.
		it("renders the same words whatever that term is renamed to", () => {
			const everyKind = [
				aWarning({ notHonouredReason: "OutsideThisPortfolio" }),
				aWarning({ referenceId: "F-8", blockerPositionedBelow: true }),
				aWarning({ referenceId: "F-7", notHonouredReason: "InALoop" }),
				aWarning({
					referenceId: "F-6",
					notHonouredReason: "BlockerCannotBeForecast",
				}),
			];

			const { unmount } = renderIndicator({ dependencies: everyKind });
			const beforeTheRename = whatItSays();
			unmount();

			terms.blocked = "Held Up";
			renderIndicator({ dependencies: everyKind });
			const afterTheRename = whatItSays();
			terms.blocked = "Blocked";

			expect(afterTheRename).toEqual(beforeTheRename);
		});
	});
});

